// clang-format on

SDL_Texture *wallTexture;

void loadTextures(SDL_Renderer *renderer) {

  uint32_t pixels[textureSize * textureSize];
  uint32_t r, g, b, a = 255;

  for (int y = 0; y < textureSize; y++) {
    for (int x = 0; x < textureSize; x++) {
      uint8_t color = wallTextureColors[y][x];

      if (color == 1) {
        r = 192, g = 191, b = 107;
      } else if (color == 2) {
        r = 209, g = 208, b = 114;
      } else if (color == 3) {
        r = 215, g = 215, b = 117;
      } else {
        r = 0, g = 0, b = 0;
      }

      pixels[y * textureSize + x] = ((r << 24) | (g << 16) | (b << 8) | a);
    }
  }

  wallTexture =
      SDL_CreateTexture(renderer, SDL_PIXELFORMAT_RGBA8888,
                        SDL_TEXTUREACCESS_STREAMING, textureSize, textureSize);

  SDL_UpdateTexture(wallTexture, NULL, pixels, textureSize * sizeof(uint32_t));
  SDL_SetTextureScaleMode(wallTexture, SDL_SCALEMODE_NEAREST);
}
